(()=>{
const root=document.querySelector('#visualLabs');
root.innerHTML=`<div class="sectionhead"><div><div class="eyebrow">02 / THE VISUAL LAB</div><h2>Change it. Watch it. Explain it.</h2></div><span class="pill">4 NEW INTERACTIVE MODELS</span></div><p class="small">Explore ideas from your Stile lessons and the Impact unit plans. Each model includes a prediction, controls and an explanation.</p><div class="labchoices" aria-label="Choose a visual model"><button data-lab="cross" aria-pressed="true">01 · Crossing over</button><button data-lab="dna">02 · Inside DNA</button><button data-lab="rates">03 · Reaction rates</button><button data-lab="heat">04 · Heat transfer</button></div><div id="labBody"></div>`;
const Q=s=>root.querySelector(s);let lab='cross',step=0,elapsed=0,playing=false,frame=0,last=0,heat='conduction',temp=2;
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const lessons={cross:{title:'Same genes. New combinations.',prompt:'Can crossing over create new combinations of existing alleles without creating a new gene?',source:'Impact 10B01V, variation in gametes · Stile 2.3 Meiosis',answer:'Yes. Matching DNA segments are exchanged between non-sister chromatids of homologous chromosomes. The genes remain at corresponding positions, but allele combinations can change.'},dna:{title:'A cell is only the beginning.',prompt:'Is a gene separate from DNA, or is it a section of the DNA molecule?',source:'Impact 10B01V, DNA structure and function · Stile 1.1 DNA and genes',answer:'A gene is a section of DNA. A chromosome contains a long DNA molecule with associated proteins; a replicated chromosome has two sister chromatids, each containing a DNA molecule.'},rates:{title:'Brighter now. Finished sooner.',prompt:'If both glow sticks start with the same amount of reactant, will heating one necessarily produce more final product?',source:'Stile 4.2 Temperature and rates of reaction',answer:'Not in this simplified model: both reach the same theoretical final amount. The warmer reaction reaches it sooner. Initial brightness represents a faster reaction, not a larger final yield.'},heat:{title:'Three routes for thermal energy.',prompt:'Which mechanism can transfer energy across a vacuum?',source:'Stile 1.2 Conduction · 2.1 Convection · 2.3 Radiation',answer:'Radiation can cross a vacuum because electromagnetic waves do not require matter. Conduction requires interactions within matter; convection involves bulk movement of a fluid.'}};
function pause(){playing=false;cancelAnimationFrame(frame);if(Q('#labPlay'))Q('#labPlay').textContent='▶ Play';}
function svg(content,title){return `<svg viewBox="0 0 600 310" role="img" aria-label="${title}">${content}</svg>`}
const text=(x,y,s,size=16,fill='#173b3b')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" text-anchor="middle">${s}</text>`;
function render(){pause();step=0;elapsed=0;const d=lessons[lab];root.querySelectorAll('[data-lab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lab===lab));Q('#labBody').innerHTML=`<div class="labgrid"><div class="labvisual"><div class="eyebrow">${lab==='rates'?'ILLUSTRATIVE KINETIC MODEL':'SCHEMATIC · NOT TO SCALE'}</div><div id="labCanvas"></div><div class="controls" id="labControls"></div><p id="labCaption" class="small"></p></div><aside class="labnotes"><h3>${d.title}</h3><div class="reviewbox"><span class="eyebrow">PREDICT FIRST</span><p style="margin:8px 0 0">${d.prompt}</p></div><h3 id="labStage" style="margin-top:22px"></h3><p id="labExplain"></p><details><summary>Check your prediction</summary><p>${d.answer}</p></details><p class="small" style="margin-top:18px"><b>Resource connection</b><br>${d.source}</p><button id="labQuiz" class="primary">Practise exam questions →</button></aside></div>`;
Q('#labQuiz').onclick=()=>{pause();window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:lab==='cross'||lab==='dna'?'genetics':lab}));};if(lab==='cross'||lab==='dna'){Q('#labControls').innerHTML=`<button id="labBack" aria-label="Previous model step">←</button><button id="labNext" class="primary">Next step →</button><button id="labReset">Reset model</button>`;Q('#labBack').onclick=()=>{step=Math.max(0,step-1);draw()};Q('#labNext').onclick=()=>{step=Math.min(lab==='cross'?2:3,step+1);draw()};Q('#labReset').onclick=()=>{step=0;draw()};}
else{Q('#labControls').innerHTML=(lab==='rates'?`<label for="labTemperature">Warmer trial <input id="labTemperature" type="range" min="1" max="3" step="0.5" value="${temp}"> <output id="tempValue">${temp}× model rate</output></label>`:`<div class="heatmodes">${['conduction','convection','radiation'].map(m=>`<button data-heat="${m}" aria-pressed="${heat===m}">${m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div>`)+`<button id="labPlay" class="primary">▶ Play</button><button id="labStep">Advance 5 model seconds</button><button id="labReset">Reset model</button>`;
Q('#labPlay').onclick=()=>{if(playing){pause();return}if(elapsed>=60)elapsed=0;playing=true;last=performance.now();Q('#labPlay').textContent='Ⅱ Pause';frame=requestAnimationFrame(tick)};Q('#labStep').onclick=()=>{pause();elapsed=Math.min(60,elapsed+5);draw()};Q('#labReset').onclick=()=>{pause();elapsed=0;draw()};if(lab==='rates')Q('#labTemperature').oninput=e=>{pause();temp=+e.target.value;elapsed=0;Q('#tempValue').textContent=`${temp}× model rate`;draw()};else root.querySelectorAll('[data-heat]').forEach(b=>b.onclick=()=>{pause();elapsed=0;heat=b.dataset.heat;root.querySelectorAll('[data-heat]').forEach(x=>x.setAttribute('aria-pressed',x===b));draw()});}
if(reduce&&Q('#labPlay')){Q('#labPlay').disabled=true;Q('#labPlay').textContent='Reduced motion · use steps';}draw();}
function tick(now){if(!playing)return;elapsed=Math.min(60,elapsed+Math.min(.05,(now-last)/1000)*2);last=now;draw();if(elapsed>=60)pause();else frame=requestAnimationFrame(tick)}
function cross(){const swapped=step===2;let c='';let cols=['#bd693f','#bd693f','#5074b6','#5074b6'],xs=[170,210,350,390];
for(let i=0;i<4;i++){c+=`<path d="M${xs[i]} 65V155" stroke="${cols[i]}" stroke-width="13" stroke-linecap="round"/>`+text(xs[i],48,i<2?'A':'a',19);c+=`<g class="exchangeTip" style="transform:translateX(${swapped?(i===1?140:i===2?-140:0):0}px)"><path d="M${xs[i]} 155V230" stroke="${cols[i]}" stroke-width="13" stroke-linecap="round"/>${text(xs[i],260,i<2?'B':'b',19)}</g>`;}
c+=`<path d="M170 120H210M350 120H390" stroke="#173b3b" stroke-width="5"/>`;
let overlay='';if(step===1)overlay+=`<path d="M225 180Q280 110 335 180M225 180Q280 250 335 180" stroke="#238780" stroke-width="2" fill="none" stroke-dasharray="5 4"/>`+text(280,295,'Exchange matching segments of the inner chromatids',13);
if(swapped)overlay+=text(280,295,'Products: AB · Ab · aB · ab',16);
if(!Q('#crossSvg'))Q('#labCanvas').innerHTML=`<svg id="crossSvg" viewBox="0 0 600 310" role="img" aria-label="Two homologous chromosomes with four chromatids; inner non-sister chromatids exchange corresponding segments">${c}<g id="crossOverlay">${overlay}</g></svg>`;
else {Q('#crossSvg').querySelectorAll('.exchangeTip').forEach((g,i)=>g.style.transform=`translateX(${swapped?(i===1?140:i===2?-140:0):0}px)`);Q('#crossOverlay').innerHTML=overlay;}
Q('#labStage').textContent=['1 · Replicated homologues','2 · Non-sister chromatids meet','3 · Recombinant chromatids'][step];Q('#labExplain').textContent=['Each homologue has two sister chromatids. This example begins with AB on one homologue and ab on the other. A/a and B/b are alleles at two corresponding gene locations.','In prophase I, homologous chromosomes pair. A crossover can exchange corresponding DNA segments between two non-sister chromatids. The inner two chromatids are the ones selected in this example.','The two outer chromatids retain AB and ab. The two inner chromatids now carry Ab and aB. New combinations of existing alleles have formed; crossing over has not created a new allele.'][step];Q('#labCaption').textContent='Colour tracks chromosome origin. The short horizontal bars join sister chromatids at their centromeres. One simplified crossover is shown.';
}
function dna(){let c='';if(step===0)c=`<ellipse cx="300" cy="145" rx="230" ry="125" fill="#e4edd6" stroke="#90aaa1" stroke-width="2"/><ellipse cx="300" cy="145" rx="95" ry="80" fill="#d9e8ef" stroke="#5074b6"/>${text(300,150,'Nucleus',24)}${text(460,250,'Animal cell',16)}<path d="M250 105q30 80 55 10t40 80M260 185q40-90 75-10" fill="none" stroke="#5074b6" stroke-width="5"/>`;
if(step===1)c=`<path d="M245 50L355 250M355 50L245 250" stroke="#5074b6" stroke-width="24" stroke-linecap="round"/><circle cx="300" cy="150" r="11" fill="#173b3b"/>${text(300,292,'One replicated chromosome · two sister chromatids',16)}`;
if(step>=2){let a='',b='';for(let x=70;x<=530;x+=5){let y=145+45*Math.sin((x-70)/35);a+=(x===70?'M':'L')+x+' '+y;b+=(x===70?'M':'L')+x+' '+(290-y)}c=`<path d="${a}" stroke="#238780" stroke-width="5" fill="none"/><path d="${b}" stroke="#5074b6" stroke-width="5" fill="none"/>`;for(let x=75,i=0;x<530;x+=23,i++){let y=145+45*Math.sin((x-70)/35);c+=`<path d="M${x} ${y}V${290-y}" stroke="${i%2?'#bd693f':'#c3b45b'}" stroke-width="3"/>`;}if(step===3)c+=`<rect x="210" y="80" width="150" height="135" rx="12" fill="#eaa17833" stroke="#bd693f" stroke-width="2"/>${text(285,245,'Gene: a section of DNA',20)}`;else c+=text(300,245,'One chromatid contains a DNA double helix',19);}
Q('#labCanvas').innerHTML=svg(`<g class="labappear">${c}</g>`,['Animal cell and its nucleus','A replicated chromosome with two sister chromatids','A DNA double helix','A gene highlighted as a section of DNA'][step]);Q('#labStage').textContent=['1 · Cell and nucleus','2 · Packaged DNA','3 · DNA double helix','4 · Gene'][step];Q('#labExplain').textContent=['In this animal-cell model, the nucleus contains most of the cell’s DNA. Mitochondria also contain some DNA. Prokaryotes do not have a nucleus.','DNA is associated with proteins and packaged into chromosomes. This X is a replicated chromosome: two sister chromatids, each with its own DNA molecule. Chromosomes are not always condensed into visible X shapes.','A DNA molecule has two complementary strands. A pairs with T; C pairs with G. The two strands of a DNA double helix are not the same as two sister chromatids.','A gene is a section of DNA, not a separate object next to it. Protein-coding genes provide information used to make proteins via RNA. Different versions of a gene are called alleles.'][step];Q('#labCaption').textContent='Conceptual zoom: shapes and sizes are simplified. The highlighted segment represents a gene, not a realistic gene length.';}
function rates(){let t=elapsed,k=.06,tempK=k*temp;const amount=(a,x)=>100*(1-Math.exp(-a*x));let c=`<path d="M70 40V240H550" stroke="#173b3b" fill="none"/>`;for(let v of [0,50,100]){let y=240-v*1.8;c+=text(43,y+4,''+v,12)+`<path d="M70 ${y}H550" stroke="#d6ddd4" stroke-dasharray="4 4"/>`;}c+=text(310,275,'Model time (0–60; arbitrary units)',14)+text(190,24,'Product formed (% of maximum)',14);for(let [a,col] of [[k,'#5074b6'],[tempK,'#bd693f']]){let path='';for(let x=0;x<=t;x+=.25)path+=(x===0?'M':'L')+(70+x*8)+' '+(240-amount(a,x)*1.8);c+=`<path d="${path}" stroke="${col}" stroke-width="4" fill="none"/><circle cx="${70+t*8}" cy="${240-amount(a,t)*1.8}" r="5" fill="${col}"/>`;}Q('#labCanvas').innerHTML=svg(c,'Product versus model time: warmer and reference reactions approach the same maximum, with the warmer trial rising faster')+`<div class="glows"><div><span>Reference trial</span><div class="glow" style="background:rgba(80,116,182,${.12+.88*Math.exp(-k*t)/3});box-shadow:0 0 ${18*Math.exp(-k*t)}px #5074b6"></div><b>${amount(k,t).toFixed(1)}% product</b></div><div><span>Warmer trial</span><div class="glow" style="background:rgba(189,105,63,${.12+.88*temp*Math.exp(-tempK*t)/3});box-shadow:0 0 ${18*temp*Math.exp(-tempK*t)}px #bd693f"></div><b>${amount(tempK,t).toFixed(1)}% product</b></div></div>`;
Q('#labStage').textContent=`Time ${t.toFixed(1)} · compare slope and brightness`;Q('#labExplain').textContent='Higher temperature raises average kinetic energy. More collisions have sufficient energy to react, so the reaction is faster. With the same starting amounts and this model’s assumptions, the theoretical final amount stays the same. A brighter initial glow can fade sooner.';Q('#labCaption').textContent='Illustrative first-order curves, not measured glow-stick data. The slider changes a model rate factor, not degrees Celsius. Brightness is qualitative; equal final yield is an assumption, not a rule for every reaction.';}
function heatDraw(){let t=elapsed,c='',desc='';if(heat==='conduction'){c=`<rect x="55" y="55" width="490" height="190" rx="15" fill="#e1e8df"/>${text(78,30,'Hot end',16,'#a74724')}${text(505,30,'Cool end',16,'#5074b6')}`;for(let col=0;col<10;col++)for(let row=0;row<4;row++){let warm=Math.max(0,Math.min(1,(t/6-col)/3));let amp=2+warm*6;let x=82+col*48+Math.sin(t*7+col+row)*amp,y=85+row*45+Math.cos(t*5+row)*amp;c+=`<circle cx="${x}" cy="${y}" r="9" fill="rgb(${Math.round(80+warm*109)},${Math.round(116-warm*11)},${Math.round(182-warm*119)})"/>`;}desc='Particles vibrate around fixed positions and transfer energy through interactions. There is no bulk flow of the solid. In metals, mobile electrons also transfer energy; they are not shown here.';}
if(heat==='convection'){c=`<rect x="65" y="40" width="470" height="225" rx="15" fill="#e3edf0" stroke="#90aaa1"/><path d="M120 285H225" stroke="#bd693f" stroke-width="9"/>${text(170,310,'Heater',13)}`;for(let i=0;i<24;i++){let a=i/24*Math.PI*2+t*.4;let x=300+170*Math.cos(a),y=152+82*Math.sin(a);let warm=x<300;c+=`<circle cx="${x}" cy="${y}" r="8" fill="${warm?'#bd693f':'#5074b6'}"/>`;}c+=text(155,25,'Warm fluid rises ↑',14)+text(445,25,'Cooler fluid sinks ↓',14);desc='Heating a fluid usually makes it expand and become less dense. Warmer fluid rises while cooler, denser fluid sinks, carrying thermal energy in a circulation. This model assumes heating from below and cooling above.';}
if(heat==='radiation'){c=`<circle cx="75" cy="150" r="40" fill="#bd693f"/><circle cx="520" cy="150" r="30" fill="#5074b6"/>${text(75,225,'Hot object',14)}${text(520,225,'Cooler object',14)}${text(300,45,'Vacuum: no particles needed',17)}`;for(let row of [-1,0,1]){let p='';for(let x=125;x<=475;x+=5)p+=(x===125?'M':'L')+x+' '+(150+row*40+12*Math.sin(x/14-t*5));c+=`<path d="${p}" stroke="#bd693f" stroke-width="3" fill="none"/>`;}c+=text(300,275,'Net energy transfer →',17);desc='Electromagnetic radiation transfers energy through space, including a vacuum. Both objects emit radiation; this diagram shows the stronger net transfer from the hotter object to the cooler one. Waves and colours are symbolic, not a view of invisible infrared.';}
Q('#labCanvas').innerHTML=svg(c,heat+' model. '+desc);Q('#labStage').textContent=heat[0].toUpperCase()+heat.slice(1);Q('#labExplain').textContent=desc;Q('#labCaption').textContent='Motion is greatly slowed and simplified. Heat is energy transferred because of a temperature difference; it is not a substance carried by the coloured dots.';}
function draw(){if(lab==='cross')cross();if(lab==='dna')dna();if(lab==='rates')rates();if(lab==='heat')heatDraw();if(Q('#labBack')){Q('#labBack').disabled=step===0;Q('#labNext').disabled=step===(lab==='cross'?2:3)}}
window.addEventListener('science-model-topic',e=>{if(['rates','heat'].includes(e.detail)){lab=e.detail;render();root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}});root.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{lab=b.dataset.lab;render()});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});render();
})();
